Jobs = [1, 2, 3]
Machines = [1, 2]
proces_time = [[1, 3], [2, 2], [3, 1]]

S = model.addVars(Jobs, Machines, lb=0, name="S")
makespan = model.addVar(name="makespan")

for j in Jobs:
    for m in Machines:
        if m == 1 and j == 1:
            model.addConstr(S[j, m] >= 0)
        elif m == 1 and j > 1:
            model.addConstr(S[j, m] >= S[j-1, m] + proces_time[j-1][m-1])
        elif m > 1:
            model.addConstr(S[j, m] >= S[j, m-1] + proces_time[j-1][m-2])

for j in Jobs:
    model.addConstr(makespan >= S[j, 2] + proces_time[j-1][1])

model.setObjective(makespan, GRB.MINIMIZE)
model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
